import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int n = 0;
            while (b >= '0' && b <= '9') {
                n = n * 10 + (b - '0');
                b = readByte();
            }
            return n;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int[] head = new int[n + 1];
        int[] next = new int[2 * m + 2];
        int[] to = new int[2 * m + 2];
        int edgeCount = 1;

        int[] deg = new int[n + 1];

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            deg[u]++;
            deg[v]++;

            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        boolean[] visited = new boolean[n + 1];
        boolean[] isNeighbor = new boolean[n + 1];

        int[] queue = new int[n + 1];
        int[] component = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                int compSize = 0;
                long edgeSum = 0;

                int qHead = 0, qTail = 0;
                queue[qTail++] = i;
                visited[i] = true;

                while (qHead < qTail) {
                    int u = queue[qHead++];
                    component[compSize++] = u;
                    edgeSum += deg[u];

                    for (int e = head[u]; e != 0; e = next[e]) {
                        int v = to[e];
                        if (!visited[v]) {
                            visited[v] = true;
                            queue[qTail++] = v;
                        }
                    }
                }

                long numEdges = edgeSum / 2;
                long requiredEdges = (long) compSize * (compSize - 1) / 2;

                if (numEdges < requiredEdges) {
                    // This component is not a clique, so there is at least one missing edge.
                    int targetU = -1;
                    for (int k = 0; k < compSize; k++) {
                        int u = component[k];
                        if (deg[u] < compSize - 1) {
                            targetU = u;
                            break;
                        }
                    }

                    // Mark all neighbors of targetU
                    isNeighbor[targetU] = true;
                    for (int e = head[targetU]; e != 0; e = next[e]) {
                        isNeighbor[to[e]] = true;
                    }

                    int targetV = -1;
                    for (int k = 0; k < compSize; k++) {
                        int v = component[k];
                        if (!isNeighbor[v]) {
                            targetV = v;
                            break;
                        }
                    }

                    System.out.println(targetU + " " + targetV);
                    return;
                }
            }
        }

        System.out.println("-1");
    }
}
