const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let num = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            num = num * 10 + (buffer[offset] - 48);
            offset++;
        }
        return num;
    }

    const n = readInt();
    if (n === null) return;
    const m = readInt();

    const head = new Int32Array(n + 1).fill(-1);
    const to = new Int32Array(2 * m);
    const next = new Int32Array(2 * m);
    const deg = new Int32Array(n + 1);

    let edgeCount = 0;
    for (let i = 0; i < m; i++) {
        const u = readInt();
        const v = readInt();

        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;

        to[edgeCount] = u;
        next[edgeCount] = head[v];
        head[v] = edgeCount++;

        deg[u]++;
        deg[v]++;
    }

    const visited = new Uint8Array(n + 1);
    const compVertices = [];

    for (let i = 1; i <= n; i++) {
        if (visited[i]) continue;

        compVertices.length = 0;
        let qHead = 0;
        compVertices.push(i);
        visited[i] = 1;

        let sumDegree = 0;

        while (qHead < compVertices.length) {
            const u = compVertices[qHead++];
            sumDegree += deg[u];

            for (let e = head[u]; e !== -1; e = next[e]) {
                const v = to[e];
                if (!visited[v]) {
                    visited[v] = 1;
                    compVertices.push(v);
                }
            }
        }

        const vCount = compVertices.length;
        const eCount = sumDegree / 2;

        if (eCount < (vCount * (vCount - 1)) / 2) {
            let root = -1;
            for (let j = 0; j < vCount; j++) {
                const u = compVertices[j];
                if (deg[u] < vCount - 1) {
                    root = u;
                    break;
                }
            }

            const isNeighbor = new Uint8Array(n + 1);
            for (let e = head[root]; e !== -1; e = next[e]) {
                isNeighbor[to[e]] = 1;
            }

            for (let j = 0; j < vCount; j++) {
                const v = compVertices[j];
                if (v !== root && !isNeighbor[v]) {
                    console.log(root + " " + v);
                    return;
                }
            }
        }
    }

    console.log("-1");
}

main();
